const text = $json.text || $json.input || $json.query || "";
const operation = ($json.operation || "").toLowerCase();

let result;

if (operation === "uppercase") {
  result = text.toUpperCase();
} else if (operation === "lowercase") {
  result = text.toLowerCase();
} else if (operation === "reverse") {
  result = text.split("").reverse().join("");
} else if (operation === "word_count") {
  result = text.trim() ? text.trim().split(/\s+/).length : 0;
} else {
  // fallback → return all (safe mode)
  result = {
    original: text,
    uppercase: text.toUpperCase(),
    lowercase: text.toLowerCase(),
    reversed: text.split("").reverse().join(""),
    word_count: text.trim() ? text.trim().split(/\s+/).length : 0
  };
}

return typeof result === "string"
  ? result
  : JSON.stringify(result, null, 2);
